// This file is generated by AI.

// 诊断收集 / 筛选 / 导出的测试。

import { describe, expect, it } from 'vitest';

import type { LspDiagnostic } from '../state/store';
import {
  buildDiagnosticsExport,
  codeStats,
  collectProjectDiagnostics,
  countBySeverity,
  countEntries,
  defaultFilter,
  describeDiagnostics,
  filterDiagnosticFiles,
  isFilterPerturbed,
  presentSeverities,
  type DiagnosticFilter,
} from './model';

const PROJECT = 'C:\\Game';

function diag(line: number, character: number, severity: number, code: string, message: string): LspDiagnostic {
  return {
    range: { start: { line, character }, end: { line, character: character + 4 } },
    severity,
    code,
    message,
  };
}

const SCENE = 'C:\\Game\\game\\scene\\start.txt';
const BRANCH = 'C:\\Game\\game\\scene\\支线\\海边.txt';

const DATA: Record<string, LspDiagnostic[]> = {
  [SCENE]: [
    diag(11, 15, 1, 'WG007', '找不到或无法识别背景: bg/教室.png'),
    diag(17, 0, 2, 'WG003', '语句参数 `-next` 重复设置或与其他参数冲突'),
  ],
  [BRANCH]: [diag(3, 0, 3, 'WG001', '语句格式不规范')],
  // 没有问题的场景: 服务端推空数组, 仍算一个场景
  'C:\\Game\\game\\scene\\empty.txt': [],
  // 别的项目: 必须被前缀过滤掉
  'C:\\Other\\game\\scene\\start.txt': [diag(0, 0, 1, 'WG007', '不属于本项目')],
};

describe('collectProjectDiagnostics', () => {
  it('只收当前项目的文件, 常规场景数含没有问题的场景', () => {
    const { scenes, files } = collectProjectDiagnostics(DATA, PROJECT);
    expect(scenes).toBe(3);
    expect(files.map((file) => file.file)).toEqual(['game/scene/start.txt', 'game/scene/支线/海边.txt']);
  });

  it('行号列号转成 1 起算, 场景路径去掉 game/scene/ 前缀', () => {
    const { files } = collectProjectDiagnostics(DATA, PROJECT);
    const [first] = files[0].entries;
    expect(first.line).toBe(12);
    expect(first.column).toBe(16);
    expect(first.endLine).toBe(12);
    expect(files[0].scene).toBe('start.txt');
    expect(files[1].scene).toBe('支线/海边.txt');
  });

  it('同一文件内按位置排序', () => {
    const { files } = collectProjectDiagnostics(
      { [SCENE]: [diag(30, 0, 1, 'WG007', 'b'), diag(2, 0, 1, 'WG007', 'a')] },
      PROJECT
    );
    expect(files[0].entries.map((entry) => entry.line)).toEqual([3, 31]);
  });

  it('项目路径大小写与结尾分隔符不影响匹配', () => {
    const { scenes } = collectProjectDiagnostics(DATA, 'c:\\game\\');
    expect(scenes).toBe(3);
  });

  it('没有项目时不按前缀过滤', () => {
    expect(collectProjectDiagnostics(DATA, null).scenes).toBe(4);
  });
});

describe('诊断码与级别统计', () => {
  it('按出现次数降序给出码, 次数相同按码升序', () => {
    const { files } = collectProjectDiagnostics(DATA, PROJECT);
    expect(codeStats(files)).toEqual([
      { code: 'WG001', severity: 3, count: 1 },
      { code: 'WG003', severity: 2, count: 1 },
      { code: 'WG007', severity: 1, count: 1 },
    ]);
  });

  it('列出数据里出现过的级别', () => {
    const { files } = collectProjectDiagnostics(DATA, PROJECT);
    expect(presentSeverities(files)).toEqual([1, 2, 3]);
  });
});

describe('defaultFilter', () => {
  it('默认只开错误与警告', () => {
    const { files } = collectProjectDiagnostics(DATA, PROJECT);
    expect(defaultFilter(files).severities).toEqual([1, 2]);
  });

  it('项目里只有信息级时默认全选 (否则打开就是空的)', () => {
    const files = collectProjectDiagnostics({ [BRANCH]: DATA[BRANCH] }, PROJECT).files;
    expect(defaultFilter(files).severities).toEqual([3]);
  });
});

describe('filterDiagnosticFiles', () => {
  const { files } = collectProjectDiagnostics(DATA, PROJECT);

  it('按级别筛选, 并丢掉筛空的分组', () => {
    const result = filterDiagnosticFiles(files, { severities: [3], codes: null, query: '' });
    expect(result.map((file) => file.file)).toEqual(['game/scene/支线/海边.txt']);
  });

  it('codes 为 null 表示不限诊断码, 给了数组则只留这些', () => {
    expect(countEntries(filterDiagnosticFiles(files, { severities: [1, 2, 3], codes: null, query: '' }))).toBe(3);
    expect(countEntries(filterDiagnosticFiles(files, { severities: [1, 2, 3], codes: ['WG007'], query: '' }))).toBe(1);
    expect(countEntries(filterDiagnosticFiles(files, { severities: [1, 2, 3], codes: [], query: '' }))).toBe(0);
  });

  it('关键词同时匹配消息、文件名与诊断码', () => {
    const base = { severities: [1, 2, 3] as const, codes: null };
    expect(countEntries(filterDiagnosticFiles(files, { ...base, severities: [1, 2, 3], query: '教室' }))).toBe(1);
    expect(countEntries(filterDiagnosticFiles(files, { ...base, severities: [1, 2, 3], query: '海边' }))).toBe(1);
    expect(countEntries(filterDiagnosticFiles(files, { ...base, severities: [1, 2, 3], query: 'wg003' }))).toBe(1);
    expect(countEntries(filterDiagnosticFiles(files, { ...base, severities: [1, 2, 3], query: '不存在的东西' }))).toBe(
      0
    );
  });
});

describe('countBySeverity', () => {
  it('四个级别都数, 包括角标以前漏掉的提示级', () => {
    const { files } = collectProjectDiagnostics(
      {
        [SCENE]: [diag(0, 0, 1, 'WG007', '错误'), diag(1, 0, 4, 'WG009', '提示'), diag(2, 0, 4, 'WG009', '提示')],
      },
      PROJECT
    );
    expect(countBySeverity(files[0].entries)).toEqual({ 1: 1, 2: 0, 3: 0, 4: 2 });
  });
});

describe('isFilterPerturbed', () => {
  const fallback: DiagnosticFilter = { severities: [1, 2], codes: null, query: '' };

  it('与默认条件一致时不算偏离 (级别的先后顺序不算改动)', () => {
    expect(isFilterPerturbed({ severities: [1, 2], codes: null, query: '' }, fallback)).toBe(false);
    expect(isFilterPerturbed({ severities: [2, 1], codes: null, query: '   ' }, fallback)).toBe(false);
  });

  it('级别 / 诊断码 / 关键词任一被改动就算偏离', () => {
    expect(isFilterPerturbed({ severities: [1], codes: null, query: '' }, fallback)).toBe(true);
    expect(isFilterPerturbed({ severities: [1, 2, 3], codes: null, query: '' }, fallback)).toBe(true);
    expect(isFilterPerturbed({ severities: [1, 2], codes: ['WG007'], query: '' }, fallback)).toBe(true);
    expect(isFilterPerturbed({ severities: [1, 2], codes: null, query: '教室' }, fallback)).toBe(true);
  });
});

describe('describeDiagnostics', () => {
  const base = { scenes: 3, total: 4, visible: 4, hidden: 0, lspStatus: 'ready' } as const;

  it('一个场景的结果都还没到时是 pending, 不给数字也不说"没有发现问题"', () => {
    const described = describeDiagnostics({ ...base, scenes: 0, total: 0, visible: 0 });
    expect(described.standing).toBe('pending');
    expect(described.emptyText).toBe('还没有收到诊断结果');
    expect(described.emptyText).not.toBe('没有发现问题');
    expect(described.description).not.toContain('条问题');
  });

  it('pending 时按连接状态说明原因', () => {
    const pending = { ...base, scenes: 0, total: 0, visible: 0 };
    expect(describeDiagnostics({ ...pending, lspStatus: 'connecting' }).description).toBe('正在连接语言服务…');
    expect(describeDiagnostics({ ...pending, lspStatus: 'ready' }).description).toBe('尚未收到诊断结果');
    expect(describeDiagnostics({ ...pending, lspStatus: 'disconnected' }).description).toBe('语言服务未连接');
    expect(describeDiagnostics({ ...pending, lspStatus: 'error' }).description).toBe('语言服务出错, 暂无诊断结果');
  });

  it('收到过场景结果 (哪怕全是空数组) 才算 clear', () => {
    const described = describeDiagnostics({ ...base, total: 0, visible: 0 });
    expect(described.standing).toBe('clear');
    expect(described.emptyText).toBe('没有发现问题');
    expect(described.description).toBe('3 个场景 · 0 条问题');
  });

  it('已经收到结果后不再参考连接状态 (断线不会让已有结果失效)', () => {
    expect(describeDiagnostics({ ...base, lspStatus: 'disconnected' }).standing).toBe('problems');
  });

  it('有问题时报当前显示条数, 被挡掉的另算, 空列表交给筛选去解释', () => {
    const described = describeDiagnostics({ ...base, total: 9, visible: 4, hidden: 5 });
    expect(described.standing).toBe('problems');
    expect(described.description).toBe('3 个场景 · 4 条问题（5 条已隐藏）');
    expect(described.emptyText).toBeNull();
  });
});

describe('buildDiagnosticsExport', () => {
  it('导出 1 起算的位置与语义化的级别名', () => {
    const { files } = collectProjectDiagnostics(DATA, PROJECT);
    const parsed = JSON.parse(
      buildDiagnosticsExport({
        projectName: '测试项目',
        scope: { kind: 'project' },
        files,
        generatedAt: '2026-01-01T00:00:00.000Z',
      })
    );

    expect(parsed.project).toBe('测试项目');
    expect(parsed.generatedAt).toBe('2026-01-01T00:00:00.000Z');
    expect(parsed.scope).toEqual({ kind: 'project' });
    expect(parsed.files[0]).toEqual({
      path: SCENE,
      relPath: 'game/scene/start.txt',
      diagnostics: [
        {
          severity: 'error',
          code: 'WG007',
          line: 12,
          column: 16,
          endLine: 12,
          endColumn: 20,
          message: '找不到或无法识别背景: bg/教室.png',
        },
        {
          severity: 'warning',
          code: 'WG003',
          line: 18,
          column: 1,
          endLine: 18,
          endColumn: 5,
          message: '语句参数 `-next` 重复设置或与其他参数冲突',
        },
      ],
    });
  });
});
